node -e "
const { TokenBucket } = require('./kova.js');
let pass = 0, fail = 0;
function t(name, fn) { try { fn(); pass++; console.log('PASS:', name); } catch (e) { fail++; console.log('FAIL:', name, '-', e.message); } }

// 1. Dolu başlar
t('dolu başlar', () => {
  const b = new TokenBucket({ capacity: 5, refillPerSecond: 10, now: () => 0 });
  if (b.available() !== 5) throw new Error('beklenen 5');
});

// 2. Zamanla dolum
t('zamanla dolum', () => {
  let now = 0;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => now });
  b.tryTake(10);
  now = 500; // 0.5 saniye -> +5 jeton
  if (Math.abs(b.available() - 5) > 1e-9) throw new Error('beklenen 5, gelen ' + b.available());
  now = 2000; // tamamen dolu
  if (b.available() !== 10) throw new Error('beklenen 10, gelen ' + b.available());
});

// 3. Saat geri gider
t('saat geri gider', () => {
  let now = 1000;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 100, now: () => now });
  b.tryTake(10);
  now = 1500; // +5 jeton
  if (Math.abs(b.available() - 5) > 1e-9) throw new Error('beklenen 5');
  now = 1200; // geri gider, değişmemeli
  if (Math.abs(b.available() - 5) > 1e-9) throw new Error('geri giderde değişmesin, gelen ' + b.available());
  now = 2000; // ileri, _last hala 1500, dolum devam eder
  if (Math.abs(b.available() - 10) > 1e-9) throw new Error('beklenen 10, gelen ' + b.available());
});

// 4. tryTake false yapınca hiç düşmez
t('fail düşmez', () => {
  const b = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 0 });
  if (b.tryTake(6) !== false) throw new Error('false bekleniyordu');
  if (b.available() !== 5) throw new Error('azalmamalı');
});

// 5. msUntil yeterliyse 0
t('msUntil yeterliyse 0', () => {
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => 0 });
  if (b.msUntil(5) !== 0) throw new Error('0 bekleniyordu');
});

// 6. msUntil n > capacity -> Infinity
t('msUntil n>capacity Infinity', () => {
  const b = new TokenBucket({ capacity: 5, refillPerSecond: 10, now: () => 0 });
  b.tryTake(5);
  if (b.msUntil(6) !== Infinity) throw new Error('Infinity bekleniyordu');
});

// 7. msUntil refill 0 ve yetersiz -> Infinity
t('msUntil refill0 Infinity', () => {
  const b = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 0 });
  b.tryTake(5);
  if (b.msUntil(1) !== Infinity) throw new Error('Infinity bekleniyordu');
});

// 8. msUntil hesaplama ve yuvarlama
t('msUntil hesaplama', () => {
  let now = 0;
  const b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => now });
  b.tryTake(10); // 0 jeton
  now = 0; // sync
  // 1 jeton için 100ms gerekir (10 jeton/sn -> 1 jeton = 100ms)
  if (b.msUntil(1) !== 100) throw new Error('100 bekleniyordu, gelen ' + b.msUntil(1));
  // 3 jeton için 300ms
  if (b.msUntil(3) !== 300) throw new Error('300 bekleniyordu, gelen ' + b.msUntil(3));
});

// 9. RangeError: capacity geçersiz
t('capacity RangeError', () => {
  let err;
  try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); } catch (e) { err = e; }
  if (!(err instanceof RangeError)) throw new Error('RangeError bekleniyordu');
  try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); } catch (e) { err = e; }
  if (!(err instanceof RangeError)) throw new Error('RangeError bekleniyordu');
  try { new TokenBucket({ capacity: Infinity, refillPerSecond: 1 }); } catch (e) { err = e; }
  if (!(err instanceof RangeError)) throw new Error('RangeError bekleniyordu');
  try { new TokenBucket({ capacity: NaN, refillPerSecond: 1 }); } catch (e) { err = e; }
  if (!(err instanceof RangeError)) throw new Error('RangeError bekleniyordu');
});

// 10. RangeError: refillPerSecond geçersiz
t('refill RangeError', () => {
  try { new TokenBucket({ capacity: 5, refillPerSecond: -1 }); } catch (e) { if (!(e instanceof RangeError)) throw e; return; }
  throw new Error('RangeError bekleniyordu');
});

// 11. RangeError: tryTake/msUntil n geçersiz
t('n RangeError', () => {
  const b = new TokenBucket({ capacity: 5, refillPerSecond: 1 });
  for (const m of ['tryTake', 'msUntil']) {
    for (const bad of [0, -1, NaN, Infinity]) {
      try { b[m](bad); } catch (e) { if (!(e instanceof RangeError)) throw e; continue; }
      throw new Error(m + '(' + bad + ') RangeError fırlatmalı');
    }
  }
});

console.log('\nSonuç:', pass, 'geçti,', fail, 'başarısız');
process.exit(fail > 0 ? 1 : 0);
"

